import http.server as h
class H(h.SimpleHTTPRequestHandler):
    def end_headers(self):
        self.send_header('Cache-Control', 'no-store')
        super().end_headers()
class S(h.ThreadingHTTPServer):
    request_queue_size = 64
    daemon_threads = True
S(('', 8765), H).serve_forever()
